"""统一应用层日志 + 级别过滤

级别: debug < info < warn < error   默认 info
  · INFO 只保留：转写文本、耗时、动作结果、错误 —— 日常只看这些
  · DEBUG：拼音标注、VAD 段/参数、裁剪、自适应调整、系统表/加载细节 等
控制: 环境变量 VOICE_AGENT_LOG=debug ｜ 或 profile behavior.log_level=debug
（voice_agent 启动时会按配置调用 set_level；本模块也认环境变量）
"""
import os
import re
import threading
import time

_LOCK = threading.Lock()

_LEVELS = {"trace": 0, "debug": 1, "info": 2, "warn": 3, "error": 4}
_LEVEL = _LEVELS.get((os.environ.get("VOICE_AGENT_LOG") or "info").lower(), 2)

# INFO 白名单：转写 / 耗时 / 动作结果 / 错误（其余一律 debug）
_INFO_PAT = re.compile(r"(🎤 「|🎯 |转写「|转写 |VAD 段转写|✅ |❌ |⏱|⇒ |已启动 |已打开 |"
                       r"日志级别=|意图清单：|意图表：|意图域|⛔ )")

# 即使命中白名单也要压到 debug 的"细枝末节"（想看就 VOICE_AGENT_LOG=debug）
#  · 已注入…            = typein 注入函数自己的回话（🎤 行已说了转写与去向）
#  · 已确认写进去…      = 听写回读验证细节（同上，重复）
#  · 转写「…」 0ms 0tok = B 路复用段的转写（A 路 VAD 段转写行才是主转写）
#  · ⏱ [听写] …         = 听写分段耗时明细（⇒ 文字进框 那一行才是结论）
_FORCE_DEBUG = re.compile(r"(已注入 |已注入：|已确认写进去|转写「|⏱ \[听写\])")

_TAG_MAP = [("🎚", "MIC"), ("🎤", "ASR"), ("🔀", "ASR"), ("⛔", "INT"),
            ("✅", "ACT"), ("❌", "ERR"), ("⚠️", "WARN"), ("🎛", "SYS"),
            ("⚡", "SYS"), ("💤", "SYS"), ("🎧", "SYS"), ("📊", "SYS"),
            ("🕒", "SYS")]


def set_level(level: str):
    """运行时改级别（voice_agent 启动时按 behavior.log_level 调用）"""
    global _LEVEL
    if isinstance(level, str) and level.lower() in _LEVELS:
        _LEVEL = _LEVELS[level.lower()]
    return _LEVEL


def get_level() -> str:
    return [k for k, v in _LEVELS.items() if v == _LEVEL][0]


def _infer_level(msg: str, tag=None):
    m = str(msg)
    # ★ 告警/错误：不管调用方给的 tag 是什么，永远显示（原来 tag=MIC 时被压成 debug）
    if "⚠️" in m or "❌" in m or "⛔" in m:
        return "warn"
    if tag == "ERR":
        return "error"
    if tag == "WARN":
        return "warn"
    if _FORCE_DEBUG.search(m):
        return "debug"
    if _INFO_PAT.search(m):
        return "info"
    return "debug"


def log(msg="", tag=None, sub=None, level=None):
    # ★ 级别过滤（未显式给 level 时按内容归类；WARN/ERR 永远显示）
    lv = _LEVELS.get(level) if level else _LEVELS.get(_infer_level(str(msg), tag), 2)
    if lv is not None and lv < _LEVEL:
        return
    # ★ 时间戳精确到毫秒
    _t = time.time()
    ts = time.strftime("%H:%M:%S", time.localtime(_t)) + f".{int((_t % 1) * 1000):03d}"
    raw = str(msg)
    was_sub = raw.startswith("   ") if sub is None else bool(sub)
    body = raw.strip()
    if tag is None:
        tag = ""
        for emoji, t in _TAG_MAP:
            if body.startswith(emoji):
                tag, body = t, body[len(emoji):].lstrip()
                break
    line = f"[{ts}] {tag:<5s} {'  ' if was_sub else ''}{body}"
    with _LOCK:
        print(line, flush=True)


def debug(msg="", tag=None, sub=None):
    log(msg, tag, sub, level="debug")
